SELECT departments.budget, departments.dept_name, departments.location, employees.salary, employees.dept_id, employees.hire_date, CASE WHEN departments.budget >= 4000000 THEN 'High' WHEN departments.budget >= 1518000 THEN 'Medium' ELSE 'Low' END AS budget_tier FROM departments JOIN employees ON departments.id = employees.dept_id WHERE departments.budget BETWEEN 3055000 AND 3460000
